/** Portable acceptance from the existing full Chromium execution; never re-runs tests. */
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { copyFile, mkdir, readFile, readdir, realpath, rename, writeFile } from "node:fs/promises";
import { dirname, resolve, relative, isAbsolute } from "node:path";
import { pathToFileURL } from "node:url";
import { requiredBrowserPaths, validateBrowserReport, validateBrowserEvidence } from "./browser-report.mjs";

const platforms = { linux: "linux", darwin: "darwin", win32: "win32", "ubuntu-24.04": "linux", "macos-26-intel": "darwin", "windows-latest": "win32" };
export function chromiumShardCount(platform) {
  assert.ok(Object.hasOwn(platforms, platform), "Unknown Chromium shard platform");
  return platforms[platform] === "darwin" ? 8 : 4;
}
export function validateShardLayout(os, shards, total, shard, platform = process.platform) {
  const count = chromiumShardCount(os);
  assert.equal(platforms[os], platform, "Chromium runner differs from declared OS");
  assert.equal(total, count, "Unexpected Chromium partition count");
  assert.deepEqual(shards, Array.from({ length: count }, (_, index) => index + 1), "Incomplete or duplicate Chromium partition layout");
  assert.ok(shards.includes(shard), "Unknown Chromium partition");
}

export function selectPortableReport(report) {
  const required = new Set(requiredBrowserPaths("core").map(path => JSON.stringify(path)));
  const selected = { errors: report.errors, stats: { expected: 0, unexpected: 0, flaky: 0, skipped: 0 }, suites: [], paths: [] };
  function select(suite, parents = []) {
    const path = [...parents, suite.title];
    const specs = (suite.specs ?? []).filter(spec => required.has(JSON.stringify([...path, spec.title])));
    for (const spec of specs) selected.paths.push([...path, spec.title]);
    const suites = (suite.suites ?? []).map(child => select(child, path)).filter(Boolean);
    return specs.length || suites.length ? { ...suite, specs, suites } : null;
  }
  selected.suites = (report.suites ?? []).map(suite => select(suite)).filter(Boolean);
  selected.stats.expected = selected.paths.length;
  validateBrowserReport(selected, { count: selected.paths.length, browser: "chromium", expectedPaths: selected.paths });
  return selected;
}

export function validateShardInventory(manifests, identity) {
  const total = chromiumShardCount(identity.platform);
  assert.equal(manifests.length, total, "Missing Chromium portable shards");
  const seen = new Set(), paths = [];
  for (const manifest of manifests) {
    assert.equal(manifest.schema, 1, "Unsupported portable shard schema");
    for (const field of ["sourceSha", "runId", "runAttempt", "platform"]) assert.equal(manifest[field], identity[field], `Wrong portable shard ${field}`);
    assert.equal(manifest.total, total, "Unexpected portable shard total");
    assert.ok(Number.isInteger(manifest.shard) && manifest.shard >= 1 && manifest.shard <= total && !seen.has(manifest.shard), "Invalid or duplicate portable shard");
    seen.add(manifest.shard);
    paths.push(...manifest.paths.map(path => JSON.stringify(path)));
  }
  assert.deepEqual(paths.sort(), requiredBrowserPaths("core").map(path => JSON.stringify(path)).sort(), "Incomplete or duplicate portable scenario inventory");
}

function identity(platform = process.platform) {
  const sourceSha = execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
  assert.match(sourceSha, /^[a-f0-9]{40}$/);
  assert.equal(process.env.GITHUB_SHA, sourceSha, "Checkout differs from workflow source");
  assert.match(process.env.GITHUB_RUN_ID ?? "", /^\d+$/);
  assert.match(process.env.GITHUB_RUN_ATTEMPT ?? "", /^\d+$/);
  return { sourceSha, runId: process.env.GITHUB_RUN_ID, runAttempt: process.env.GITHUB_RUN_ATTEMPT, platform };
}

export async function extractShard(reportPath, output, shard, expectedIdentity = identity()) {
  const total = chromiumShardCount(expectedIdentity.platform);
  assert.ok(Number.isInteger(shard) && shard >= 1 && shard <= total, "Invalid Chromium shard");
  reportPath = resolve(reportPath); output = resolve(output);
  const selected = selectPortableReport(JSON.parse(await readFile(reportPath, "utf8")));
  const results = validateBrowserReport(selected, { count: selected.paths.length, browser: "chromium", expectedPaths: selected.paths });
  await mkdir(output, { recursive: true });
  for (const [index, result] of results.entries()) {
    for (const attachment of result.attachments.filter(value => ["portable-browser-evidence", "portable-browser-screenshot", "trace"].includes(value.name))) {
      const filename = `case-${index}-${attachment.name}`;
      await copyFile(resolve(dirname(reportPath), attachment.path), resolve(output, filename));
      attachment.path = filename;
    }
  }
  const filename = resolve(output, "results.json");
  await writeFile(filename, JSON.stringify(selected));
  await validateBrowserEvidence(filename, { ...expectedIdentity, expectedPaths: selected.paths });
  const manifest = { schema: 1, ...expectedIdentity, shard, total, paths: selected.paths };
  await writeFile(resolve(output, "shard.json"), JSON.stringify(manifest));
  console.log(`Validated ${selected.paths.length} portable cases in Chromium shard ${shard}/${total}`);
}

export async function collectShards(input, expectedIdentity) {
  input = await realpath(input);
  const manifests = [], roots = [];
  for (const name of await readdir(input)) {
    const root = await realpath(resolve(input, name));
    const local = relative(input, root);
    assert.ok(local && !local.startsWith("..") && !isAbsolute(local), "Portable shard escapes artifact directory");
    manifests.push(JSON.parse(await readFile(resolve(root, "shard.json"), "utf8"))); roots.push(root);
  }
  validateShardInventory(manifests, expectedIdentity);
  for (const [index, root] of roots.entries()) {
    await validateBrowserEvidence(resolve(root, "results.json"), { ...expectedIdentity, expectedPaths: manifests[index].paths });
  }
  console.log(`Validated all ${requiredBrowserPaths("core").length} ${expectedIdentity.platform} Chromium portable scenarios from ${chromiumShardCount(expectedIdentity.platform)} full-suite shards`);
}

const operatingSystems = ["ubuntu-24.04", "macos-26-intel", "windows-latest"];
export async function collectDownloadedShards(input, output, expectedIdentity, { collect = collectShards } = {}) {
  for (const os of operatingSystems) {
    const platform = platforms[os];
    const destination = resolve(output, platform);
    await mkdir(destination, { recursive: true });
    for (let shard = 1; shard <= chromiumShardCount(os); shard++) {
      await rename(resolve(input, `chromium-portable-${os}-${shard}-${expectedIdentity.runAttempt}`), resolve(destination, String(shard)));
    }
    await collect(destination, { ...expectedIdentity, platform });
  }
}

export async function renderDownloadedReports(input, output, { runAttempt, linuxResult, desktopResult }, {
  merge = (directory, os) => execFileSync(process.execPath, [resolve("node_modules/@playwright/test/cli.js"), "merge-reports", "--config", "playwright.config.ts", "--reporter=html", directory],
    { stdio: "inherit", env: { ...process.env, PLAYWRIGHT_HTML_OUTPUT_DIR: resolve("playwright-report", os) } }),
  log = console.error,
} = {}) {
  assert.match(runAttempt ?? "", /^\d+$/, "Missing workflow attempt");
  let rendered = 0;
  const failures = [];
  for (const os of operatingSystems) {
    const result = os === "ubuntu-24.04" ? linuxResult : desktopResult;
    if (result === "skipped") continue;
    if (!["success", "failure", "cancelled"].includes(result)) { failures.push(`Unknown producer conclusion for ${os}: ${result}`); continue; }
    const destination = resolve(output, os);
    await mkdir(destination, { recursive: true });
    let available = true;
    for (let shard = 1; shard <= chromiumShardCount(os); shard++) {
      try {
        const source = resolve(input, `playwright-ui-${os}-${shard}-${runAttempt}`, "blob-report");
        const blobs = (await readdir(source)).filter(name => name.endsWith(".zip"));
        assert.ok(blobs.length, "No report blobs");
        for (const blob of blobs) await copyFile(resolve(source, blob), resolve(destination, blob));
      } catch { available = false; failures.push(`Missing ${os} shard ${shard} blobs for this run attempt`); }
    }
    if (!available) continue;
    try { await merge(destination, os); rendered++; }
    catch (error) { failures.push(`Unable to render ${os}: ${error.message}`); }
  }
  for (const failure of failures) log(failure);
  assert.ok(rendered > 0 && failures.length === 0, "UI report rendering incomplete");
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const [mode, input, output] = process.argv.slice(2);
  if (mode === "extract") await extractShard(input, output, Number(process.env.CHROMIUM_SHARD));
  else if (mode === "collect") await collectShards(input, identity(output));
  else if (mode === "collect-artifacts") await collectDownloadedShards(input, output, identity());
  else if (mode === "render-artifacts") await renderDownloadedReports(input, output, { runAttempt: process.env.GITHUB_RUN_ATTEMPT, linuxResult: process.env.LINUX_RESULT, desktopResult: process.env.DESKTOP_RESULT });
  else if (mode === "shards") console.log(Array.from({ length: chromiumShardCount(input) }, (_, index) => index + 1).join(" "));
  else if (mode === "layout") validateShardLayout(process.env.CHROMIUM_OS, JSON.parse(process.env.CHROMIUM_SHARDS), Number(process.env.CHROMIUM_TOTAL), Number(process.env.CHROMIUM_SHARD));
  else throw Error("usage: chromium-evidence.mjs extract REPORT OUTPUT | collect INPUT PLATFORM | collect-artifacts INPUT OUTPUT | render-artifacts INPUT OUTPUT | shards PLATFORM | layout");
}
